void handleMap(Map map) {
  map.values().removeIf(v -> {
    if (v instanceof Map) {
        handleMap(v);
    } else if (v instanceof List) {
        handleList(v);
    }
    return v == null || v == '' || v == '-' || v == 'none' || (v instanceof Map && v.size() == 0) || (v instanceof List && v.size() == 0)
  });
}
void handleList(List list) {
  list.removeIf(v -> {
    if (v instanceof Map) {
        handleMap(v);
    } else if (v instanceof List) {
        handleList(v);
    }
    return v == null || v == '' || v == '-' || v == 'none' || (v instanceof Map && v.size() == 0) || (v instanceof List && v.size() == 0)
  });
}
handleMap(ctx);

void addFields(Set entities, List fields) {
  for (String field : fields) {
    addField(entities, field);
  }
}

void addField(Set entities, String fieldName) {
  addValue(entities, $(fieldName, null));
}

boolean addValues(Set entities, List values) {
  boolean addedAll = true;
  for (String value : values) {
    addedAll = addedAll && addValue(entities, value);
  }
  return addedAll;
}

boolean addValue(Set entities, String value) {
  if (value == null || value == "") {
    return false;
  }
  return entities.add(value);
}

